    "k010": "<span class=\"mobile-menu__group-label\">L'argument</span> <a href=\"manifesto.html\">Manifeste<span class=\"mm-desc\">La lettre — 86 références</span></a> <a href=\"standard.html\">Normes<span class=\"mm-desc\">Les quatre clauses que nous réclamons</span></a> <a href=\"manifesto.html#enki\">Pourquoi Enki<span class=\"mm-desc\">Le nom &amp; l'argument</span></a>",
